-- =====================================================================
-- SmartDocs - data db_smartdocs (PostgreSQL)
-- ---------------------------------------------------------------------
-- Dihasilkan dari dump MariaDB smartdocs_db. Literal ditulis dollar-quoted
-- karena escaping gaya MySQL tidak sah di PostgreSQL.
-- Urutan tabel mengikuti foreign key: documents dulu, anaknya menyusul.
-- Jalankan setelah 01_schema.sql: psql -d db_smartdocs -f 02_data.sql
-- =====================================================================

BEGIN;

-- documents: 191 baris

-- document_items: 715 baris

-- activity_logs: 610 baris

-- smartdocs_users: 5 baris

-- Sinkronkan sequence identity karena id diisi eksplisit di atas.
SELECT setval(pg_get_serial_sequence('documents', 'id'), (SELECT COALESCE(MAX(id), 1) FROM documents));
SELECT setval(pg_get_serial_sequence('document_items', 'id'), (SELECT COALESCE(MAX(id), 1) FROM document_items));
SELECT setval(pg_get_serial_sequence('activity_logs', 'id'), (SELECT COALESCE(MAX(id), 1) FROM activity_logs));
SELECT setval(pg_get_serial_sequence('smartdocs_users', 'id'), (SELECT COALESCE(MAX(id), 1) FROM smartdocs_users));

COMMIT;
